var I18nModeNIT = class extends BaseSetting {
  main() {
    const api = new API(this.i18n);
    const i18nModeNIT = new import_obsidian6.Setting(this.containerEl);
    i18nModeNIT.setName(`${t("\u8BBE\u7F6E_AI_\u6807\u9898")}`);
    i18nModeNIT.setDesc(t("\u8BBE\u7F6E_AI_\u63CF\u8FF0"));
    i18nModeNIT.addButton((cb) => {
      cb.setButtonText(
        this.settings.I18N_MODE_NIT ? t("\u8BBE\u7F6E_\u901A\u7528_\u5DF2\u542F\u7528") : t("\u8BBE\u7F6E_\u901A\u7528_\u5DF2\u505C\u7528")
      );
      cb.onClick(async () => {
        this.settings.I18N_MODE_NIT = !this.settings.I18N_MODE_NIT;
        this.i18n.saveSettings();
        this.settingTab.nitDisplay();
      });
      cb.setClass("i18n-button");
      cb.setClass(`is-${this.settings.I18N_BUTTON_SHAPE}`);
      cb.buttonEl.style.minWidth = "6em";
      this.settings.I18N_MODE_NIT ? cb.setClass(
        `i18n-button--${this.settings.I18N_BUTTON_TYPE}-success`
      ) : cb.setClass(
        `i18n-button--${this.settings.I18N_BUTTON_TYPE}-danger`
      );
    });
    const i18nNITAPI = new import_obsidian6.Setting(this.containerEl);
    i18nNITAPI.setName(t("\u8BBE\u7F6E_AI_\u63A5\u53E3\u670D\u52A1_\u6807\u9898"));
    i18nNITAPI.setDesc(t("\u8BBE\u7F6E_AI_\u63A5\u53E3\u670D\u52A1_\u63CF\u8FF0"));
    i18nNITAPI.addDropdown(
      (cb) => cb.addOptions(API_TYPES).setValue(this.settings.I18N_NIT_API).onChange((value) => {
        this.settings.I18N_NIT_API = value;
        this.i18n.saveSettings();
        this.settingTab.nitDisplay();
      }).selectEl.addClass("i18n-select")
    );
    i18nNITAPI.addButton(
      (cb) => cb.setButtonText(t("\u8BBE\u7F6E_\u901A\u7528_\u6D4B\u8BD5_\u6587\u672C")).onClick(async () => {
        switch (this.settings.I18N_NIT_API) {
          case "BAIDU":
            if ((await api.baiduAPI("i18n")).state)
              this.i18n.notice.result("\u767E\u5EA6", true);
            break;
          case "OPENAI":
            api.openAITest();
            break;
          default:
            break;
        }
      }).setClass("i18n-button").setClass(
        `i18n-button--${this.settings.I18N_BUTTON_TYPE}-primary`
      ).setClass(`is-${this.settings.I18N_BUTTON_SHAPE}`)
    );
    const i18nModeNITInterval = new import_obsidian6.Setting(this.containerEl);
    i18nModeNITInterval.setName(t("\u8BBE\u7F6E_AI_\u8BF7\u6C42\u95F4\u9694_\u6807\u9898"));
    i18nModeNITInterval.setDesc(t("\u8BBE\u7F6E_AI_\u8BF7\u6C42\u95F4\u9694_\u63CF\u8FF0"));
    i18nModeNITInterval.addSlider(
      (cb) => cb.setDynamicTooltip().setLimits(0, 1e3, 50).setValue(this.settings.I18N_NIT_API_INTERVAL).onChange((value) => {
        this.settings.I18N_NIT_API_INTERVAL = value;
        this.i18n.saveSettings();
      })
    );
    new import_obsidian6.Setting(this.containerEl).setName(t("\u8BBE\u7F6E_\u4E91\u7AEF_\u670D\u52A1\u914D\u7F6E_\u6807\u9898")).setHeading();
  }
};

