// src/utils/state.ts
var fs2 = __toESM(require_lib());
var State = class {
  constructor(i18n, path7) {
    this.stateJson = { "type": "0", "state": false, "pluginVersion": "", "translationVersion": 0 };
    this.path = path7;
    this.isStateDoc = fs2.pathExistsSync(this.path);
    this.stateObj = this.isStateDoc ? fs2.readJsonSync(this.path) : void 0;
  }
  getType() {
    return this.stateObj.type;
  }
  getState() {
    return this.stateObj.state;
  }
  getPluginVersion() {
    return this.stateObj.pluginVersion;
  }
  getTranslationVersion() {
    return this.stateObj.translationVersion;
  }
  setType(v) {
    this.stateObj.type = v;
    fs2.outputJsonSync(this.path, this.stateObj);
  }
  setState(v) {
    this.stateObj.state = v;
    fs2.outputJsonSync(this.path, this.stateObj);
  }
  setPluginVersion(v) {
    this.stateObj.pluginVersion = v;
    fs2.outputJsonSync(this.path, this.stateObj);
  }
  setTranslationVersion(v) {
    this.stateObj.translationVersion = v;
    fs2.outputJsonSync(this.path, this.stateObj);
  }
  // 增
  insert() {
    try {
      this.stateObj = this.stateJson;
      this.isStateDoc = true;
      fs2.outputJsonSync(this.path, this.stateJson);
    } catch (e) {
      this.i18n.notice.result("\u65B0\u589E\u72B6\u6001\u6587\u4EF6", false, e);
    }
  }
  // 删
  delete() {
    try {
      this.isStateDoc = false;
      fs2.removeSync(this.path);
    } catch (e) {
      this.i18n.notice.result("\u5220\u9664\u72B6\u6001\u6587\u4EF6", false, e);
    }
  }
  // 改
  update(t2, s, p, v) {
    const state = { "type": t2, "state": s, "pluginVersion": p, "translationVersion": v };
    this.stateObj = state;
    try {
      fs2.outputJsonSync(this.path, state);
    } catch (e) {
      this.i18n.notice.result("\u4FEE\u6539\u72B6\u6001\u6587\u4EF6", false, e);
    }
  }
  // [重置]
  reset() {
    try {
      fs2.outputJsonSync(this.path, this.stateJson);
      console.log(this.stateJson);
    } catch (e) {
      this.i18n.notice.result("\u91CD\u7F6E\u72B6\u6001\u6587\u4EF6", false, e);
    }
  }
};

// src/utils/translation.ts
function generatePlugin(pluginVersion, manifestJSON, mainStr, reLength, regexps, flags) {
  const description = manifestJSON.description;
  const translationJson = {
    "manifest": {
      "translationVersion": Date.now(),
      "pluginVersion": pluginVersion
    },
    "description": {
      "original": description,
      "translation": description
    },
    "dict": {}
  };
  for (let i2 = 0; i2 < regexps.length; i2++) {
    const temp_array = mainStr.match(new RegExp(regexps[i2], flags));
    if (temp_array != null) {
      for (const i3 in temp_array)
        if (temp_array[i3].length <= reLength)
          translationJson.dict[temp_array[i3]] = temp_array[i3];
    }
  }
  return translationJson;
}
function generateTheme(themeManifest, themeStr) {
  const themeJson = {
    "manifest": {
      "translationVersion": 0,
      "pluginVersion": themeManifest.version
    },
    "dict": {}
  };
  const match = themeStr.match(/(?:\/\* @settings)([\s\S]*?)(?:\*\/)/);
  if (match) {
    const regex = /title:\s*([^\n]*)|description:\s*([^\n]*)/mg;
    const matches = match[0].match(regex);
    if (matches) {
      matches.forEach((match2) => {
        themeJson.dict[match2] = match2;
      });
    }
  } else {
    console.log("\u6CA1\u6709\u627E\u5230\u5339\u914D\u7684\u5185\u5BB9");
  }
  return themeJson;
}

// src/utils/version.ts
var compareVersions = (version1, version2) => {
  if (typeof version1 !== "string" || typeof version2 !== "string")
    throw new TypeError("\u7248\u672C\u53F7\u5FC5\u987B\u4E3A\u5B57\u7B26\u4E32\u7C7B\u578B");
  if (!version1 || !version2)
    throw new Error("\u7248\u672C\u53F7\u4E0D\u80FD\u4E3A\u7A7A\u5B57\u7B26\u4E32");
  const versionRegex = /^\d+\.\d+\.\d+(-[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?(\+[0-9A-Za-z-]+)?$/;
  if (!versionRegex.test(version1) || !versionRegex.test(version2))
    throw new Error("\u7248\u672C\u53F7\u683C\u5F0F\u4E0D\u7B26\u5408 SemVer \u89C4\u8303");
  const { coreVersion: core1, preRelease: pre1 } = parseVersion(version1);
  const { coreVersion: core2, preRelease: pre2 } = parseVersion(version2);
  const v1 = core1.split(".").map((segment) => {
    const num = Number(segment);
    return isNaN(num) ? 0 : num;
  });
  const v2 = core2.split(".").map((segment) => {
    const num = Number(segment);
    return isNaN(num) ? 0 : num;
  });
  const len = Math.max(v1.length, v2.length);
  for (let i2 = 0; i2 < len; i2++) {
    const num1 = v1[i2] || 0;
    const num2 = v2[i2] || 0;
    if (num1 > num2)
      return 1;
    if (num1 < num2)
      return -1;
  }
  if (pre1 === null && pre2 === null)
    return 0;
  if (pre1 === null)
    return 1;
  if (pre2 === null)
    return -1;
  const pre1Parts = pre1.split(".");
  const pre2Parts = pre2.split(".");
  const maxPreLen = Math.max(pre1Parts.length, pre2Parts.length);
  for (let i2 = 0; i2 < maxPreLen; i2++) {
    const part1 = pre1Parts[i2] || "";
    const part2 = pre2Parts[i2] || "";
    const num1 = Number(part1);
    const num2 = Number(part2);
    const isNum1 = !isNaN(num1);
    const isNum2 = !isNaN(num2);
    if (isNum1 && isNum2) {
      if (num1 > num2)
        return 1;
      if (num1 < num2)
        return -1;
    } else if (isNum1) {
      return -1;
    } else if (isNum2) {
      return 1;
    } else {
      if (part1 > part2)
        return 1;
      if (part1 < part2)
        return -1;
    }
  }
  return 0;
};
var parseVersion = (version2) => {
  const [mainPart] = version2.split("+");
  const [coreVersion, preRelease] = mainPart.split("-");
  return { coreVersion, preRelease: preRelease || null };
};

// src/utils/validation.ts
var isValidpluginTranslationFormat = (pluginJson) => {
  if (!pluginJson)
    return false;
  const hasManifest = "manifest" in pluginJson;
  const hasDict = "dict" in pluginJson;
  const hasDescription = "description" in pluginJson;
  const hasTranslationVersion = hasManifest && "translationVersion" in pluginJson.manifest;
  const hasPluginVersion = hasManifest && "pluginVersion" in pluginJson.manifest;
  const hasOriginal = hasDescription && "original" in pluginJson.description;
  const hasTranslation = hasDescription && "translation" in pluginJson.description;
  return hasManifest && hasTranslationVersion && hasPluginVersion && hasDict && hasDescription && hasOriginal && hasTranslation;
};
var isValidThemeTranslationFormat = (themeJson) => {
  if (!themeJson)
    return false;
  const hasThemeManifest = "manifest" in themeJson;
  const hasThemeTranslationVersion = hasThemeManifest && "translationVersion" in themeJson.manifest;
  const hasThemeVersion = hasThemeManifest && "pluginVersion" in themeJson.manifest;
  const hasThemeDict = "dict" in themeJson;
  return hasThemeManifest && hasThemeTranslationVersion && hasThemeVersion && hasThemeDict;
};

