                const modifiedTranslationJson = generatePlugin(theme.version, fs8.readJsonSync(manifestDoc), fs8.readFileSync(mainDoc).toString(), this.settings.I18N_RE_LENGTH, this.regexps, this.settings.I18N_RE_FLAGS);
                modifiedTranslationJson.manifest = originalTranslationJson.manifest;
